CREATE OR REPLACE FUNCTION public.verify_certificate(p_serial text)
 RETURNS json
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select json_build_object(
    'serial',      a.serial,
    'title',       d.title,
    'subtitle',    d.subtitle,
    'body',        d.body,
    'tier',        d.tier,
    'accent',      d.accent,
