    'signature_role', d.signature_role,
    'footnote',    d.footnote,
    'award_on',    d.award_on,
    'options',     d.options,
    'facts',       a.facts,
    'awarded_at',  a.awarded_at,
    'photo',       p.photo_url
  )
  from public.certificate_awards a
  join public.certificate_designs d on d.id = a.design_id
  join public.profiles p on p.id = a.profile_id
